window.HCF_PLATFORM="python";
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+(Number(n)/100).toLocaleString('en-IN',{maximumFractionDigits:0});
const day=d=>new Date(d.length===10?d+'T12:00:00+05:30':d).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'});
const due=(start,round)=>{const[y,m,d]=start.split('-').map(Number),last=new Date(Date.UTC(y,m+round,0)).getUTCDate();return new Date(Date.UTC(y,m-1+round,Math.min(d,last))).toISOString().slice(0,10)};
const initials=name=>String(name||'Member').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
let demoAccounts=null;
let me=null,circles=[],pageData=null,detailTab='overview',navEpoch=0,busy=false,recoveryToken=null,checkoutStep='payment',checkoutChoice={method:'test_card',scenario:'approved',orderId:null};
let searchText='',toastTimer;const route=()=>location.hash.slice(1)||'overview';
const own=g=>g.members?.find(m=>m.userId===me?.id),paid=(g,r=g.round)=>g.payments?.filter(p=>p.round===r&&p.status==='succeeded')||[],funded=g=>paid(g).length===g.capacity&&new Set(paid(g).map(p=>p.userId)).size===g.capacity&&paid(g).reduce((n,p)=>n+p.amount,0)===g.amount*g.capacity;
const notice=message=>`<div class="notice"><p>${message}</p></div>`;
const nav=[['overview','Overview','▦'],['circles','My circles','◎'],['explore','Find a circle','✧'],['payments','Payments','⇄'],['schedule','Payout schedule','▤'],['organizer','Organizer desk','◇'],['notifications','Notifications','♧'],['account','My account','○'],['principles','Our principles','❋']];
const badge=status=>`<span class="pill ${['succeeded','active','completed','approved'].includes(status)?'good':['failed','rejected','cancelled'].includes(status)?'bad':['pending','paused','expired'].includes(status)?'warn':'neutral'}">${esc({succeeded:'Completed',deleted:'Deleted',forming:'Forming',active:'Active',completed:'Completed',pending:'Pending',paused:'Paused',failed:'Declined',approved:'Approved',rejected:'Declined',cancelled:'Cancelled',expired:'Expired'}[status]||status)}</span>`;
class ApiError extends Error{constructor(message,status){super(message);this.status=status}}
async function api(path,data){let r;try{r=await fetch('/api'+path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'content-type':'application/json'}:{},...(data?{body:JSON.stringify({operationId:crypto.randomUUID(),...data})}:{})})}catch{throw new ApiError('You appear to be offline. Reconnect and try again.',0)}const result=await r.json().catch(()=>({error:'The server returned an unexpected response.'}));if(!r.ok)throw new ApiError(result.error||'This request could not be completed.',r.status);return result}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function modal(title,html){$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" aria-label="Close dialog">×</button></div>${html}<div id="modal-error" class="error-message" role="alert"></div>`;if(!$('#modal').open)$('#modal').showModal();$('.close').onclick=()=>{if(!busy)$('#modal').close()}}
const close=()=>$('#modal').close();
async function run(form,callback){if(busy)return;busy=true;const buttons=$$('#content button,#modal button');buttons.forEach(b=>{b.dataset.disabled=b.disabled?'1':'0';b.disabled=true});let error=form?.querySelector('.inline-error,.auth-error')||$('#modal-error');if(error)error.textContent='';try{await callback()}catch(e){error=form?.querySelector('.inline-error,.auth-error')||($('#modal').open?$('#modal-error'):null);if(error){error.textContent=e.message;error.scrollIntoView({block:'nearest'})}else toast(e.message)}finally{busy=false;buttons.forEach(b=>{b.disabled=b.dataset.disabled==='1';delete b.dataset.disabled})}}
async function sync(){const d=await api('/home');me=d.user;circles=d.circles;return d}
function activity(){return[...new Map(circles.filter(g=>!g.preview).flatMap(g=>g.events.map(e=>({...e,circleName:g.name,circleId:g.id}))).map(e=>[e.id,e])).values()].sort((a,b)=>b.at.localeCompare(a.at))}
function transactions(){return circles.filter(g=>!g.preview).flatMap(g=>[...g.payments.map(p=>({...p,type:'Contribution',circleName:g.name,circleId:g.id})),...g.payouts.map(p=>({...p,type:'Payout',circleName:g.name,circleId:g.id}))]).filter(p=>p.userId===me?.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
function layout(key,mode){document.body.dataset.mode=mode||(!me?'public':key==='checkout'?'checkout':'app');$('#page-heading').hidden=!me||key==='checkout'||key==='receipt';$('#nav').innerHTML=me?nav.map(([id,label,icon])=>`<a href="#${id}" class="${(key===id||(['circle','join'].includes(key)&&id==='circles'))?'active':''}" ${(key===id||(['circle','join'].includes(key)&&id==='circles'))?'aria-current="page"':''} title="${label}"><span class="nav-icon">${icon}</span><span class="nav-label">${label}</span>${id==='circles'?`<span class="count">${circles.filter(g=>!g.preview).length}</span>`:''}</a>`).join(''):'';const unread=me&&activity().some(e=>!me.notificationsReadAt||e.at>me.notificationsReadAt);$('#header-actions').innerHTML=me?`<span class="live-test"><i></i><span>Test payments · No real money</span><b class="mobile-test" hidden>TEST MODE</b></span><button class="top-icon" data-action="refresh" aria-label="Refresh saved records">↻</button><a class="top-icon" href="#notifications" aria-label="Notifications"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${unread?'<b></b>':''}</a><button class="avatar small" data-action="account" aria-label="My account">${esc(initials(me.name))}</button>`:`<div class="public-nav"><a class="text-btn principles-link" href="#principles">Our principles</a><a class="text-btn" href="#login">Sign in</a><a class="primary" href="#signup">Create account →</a></div>`;if(me){$('#profile-name').textContent=me.name;$('#profile-initials').textContent=initials(me.name)}const titles={overview:['Your savings, in good company.','Welcome back, '+(me?.name?.split(' ')[0]||'friend')+'. Build your next milestone, together.'],circles:['Your circles.','Shared commitments. Personal milestones.'],explore:['Find your people. Fund your goals.','Join an open circle or use a private invitation link.'],payments:['Every payment, accounted for.','Your test contributions, payout records, and receipts.'],schedule:['Your turn is on the calendar.','A fixed order. Equal contributions. One payout per member.'],organizer:['Keep your circle moving.','Invite members, approve requests and manage funded test payouts.'],notifications:['Stay in the circle.','Updates from the circles you belong to.'],account:['Your account, your commitment.','Manage your profile and account access.'],principles:['Good intentions. Clear commitments.','An interest-free model built around shared responsibility.']};const t=titles[key]||titles.circles;$('#page-title').innerHTML=esc(t[0]).replace(/\.$/,'<span>.</span>');$('#page-subtitle').textContent=t[1];$('#crumb').textContent=nav.find(n=>n[0]===key)?.[1]||'Circle';$('#page-action').innerHTML=me&&['overview','circles','organizer'].includes(key)?'<button class="primary" data-action="create">＋ Create a circle</button>':'';}
function empty(title,description,label,action){return `<div class="empty-panel"><h3>${esc(title)}</h3><p>${esc(description)}</p>${label?`<button class="secondary" ${action?.startsWith('#')?`data-go="${esc(action.slice(1))}"`:`data-action="${esc(action)}"`}>${esc(label)} →</button>`:''}</div>`}
function landing(){return `<div class="landing"><section class="landing-hero"><div class="landing-copy"><span class="pill">✧ SAVING, WITH SHARED PURPOSE</span><h1>Small commitments.<br>Meaningful possibilities<span>.</span></h1><p>Bring your community together in an interest-free savings circle. Contribute regularly, follow a clear payout order, and make room for what matters.</p><div class="landing-actions"><a class="primary" href="#signup">Start your savings journey →</a><a class="text-btn" href="#login">Already a member? Sign in</a></div><div class="landing-note"><span>✓ Equal contributions</span><span>✓ No bidding or interest</span><span>✓ Transparent schedules</span></div></div><div class="landing-visual"><h3>GROW BETTER, TOGETHER.</h3><div class="mini-savings-card"><small>HOW A CIRCLE WORKS · EXAMPLE</small><strong>₹12,000</strong><p>6 members × ₹2,000 each month.<br>One equal pool. A fair turn for everyone.</p><div class="progress"><div style="width:66%"></div></div></div><div class="plant-art" aria-hidden="true"><div class="orbit"></div><div class="stem"></div><div class="leaf"></div><div class="leaf two"></div><div class="leaf three"></div><div class="pot"></div><div class="coin">✦</div><div class="coin two">✦</div></div><div class="landing-caption">Illustrative amounts. Payments on this platform are simulated.</div></div></section><section class="landing-benefits">${[['◎','Create your circle','Set the monthly contribution, group size and first due date. Invite people you know, or open your circle to new members.'],['▤','Know where you stand','See membership, payment status and the full payout schedule. Every approved member has one fixed turn.'],['✓','Try the complete payment flow','Use the built-in test gateway to contribute, receive receipts and follow a funded payout. No real money is collected.']].map(a=>`<article class="landing-benefit"><span>${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p></article>`).join('')}</section><section class="project-team" id="project-team" aria-labelledby="project-team-title"><div class="eyebrow">THE PEOPLE BEHIND THE PROJECT</div><h2 id="project-team-title">Meet our project team<span>.</span></h2><p>Bringing community savings online, together.</p><ul class="project-team-grid">${['Shehzeen Fatima','Shaik Asefa','maryam Mohd','nabeehunnisa'].map((name,i)=>`<li class="project-team-card"><span class="project-team-number" aria-hidden="true">0${i+1}</span><h3>${name}</h3><span class="project-team-label">Project team member</span></li>`).join('')}</ul></section><div class="landing-bottom">Real user accounts and shared circles. Clearly marked test payments.<br>Interest-free design; formal Shariah certification is not claimed. <a class="text-btn" href="#principles">Read our principles →</a></div></div>`}
function demoLogins(){return demoAccounts?.accounts?.length?`<section class="demo-logins" aria-label="Demo login accounts"><span class="pill warn">SHARED UNIVERSITY DEMO</span><h2>Try a ready-made account</h2><p>Use these fake login IDs to explore the website. Records are shared with other visitors. Use test data only.</p><div class="demo-login-list">${demoAccounts.accounts.map(a=>`<button type="button" class="demo-login-choice" data-demo-email="${esc(a.email)}"><b>${esc(a.name)}</b><small>${esc(a.role)} · ${esc(a.email)}</small></button>`).join('')}</div><p>Password for each account: <code>${esc(demoAccounts.password)}</code></p><small>Select a name to fill the form, then press Sign in. OTP for fake payments: <b>123456</b>.</small></section>`:''}
function authView(kind,message=''){const signup=kind==='signup',forgot=kind==='forgot-password',reset=kind==='reset-password';return `<div class="auth-layout">${kind==='login'?demoLogins():''}<div class="panel"><div class="eyebrow">HALAL CHIT FUND</div><h1>${signup?'A new chapter starts here.':forgot?'Let’s get you back in.':reset?'Choose a new password.':'Welcome back to your circle.'}</h1><p>${signup?'Create your own account to organize or join shared savings circles.':forgot?'Enter your account email. We’ll send a password reset link if an account exists.':reset?'Use a password you don’t use for another service.':'Sign in to your saved circles and contribution records.'}</p>${message?`<div class="auth-message">${esc(message)}</div>`:''}<form id="auth-form" data-kind="${kind}">${signup?'<label for="auth-name">Full name</label><input id="auth-name" name="name" autocomplete="name" minlength="2" maxlength="60" required>':''}${!reset?'<label for="auth-email">Email address</label><input id="auth-email" type="email" autocomplete="email" maxlength="254" required>':''}${!forgot?`<label for="auth-password">${reset?'New password':'Password'}</label><input id="auth-password" type="password" autocomplete="${signup||reset?'new-password':'current-password'}" minlength="${signup||reset?'10':'1'}" maxlength="128" required>${signup||reset?'<p class="hint">Use at least 10 characters and avoid reusing a password from another website.</p>':''}`:''}${signup?'<label class="check"><input type="checkbox" id="auth-terms" required><span>I am an adult and understand that this service currently uses simulated payments, with no real money collected or paid out.</span></label>':''}<div class="auth-error" role="alert"></div><button class="primary">${signup?'Create account':forgot?'Send reset link':reset?'Save new password':'Sign in'} →</button></form><div class="auth-links">${signup?'<a href="#login">Already have an account? Sign in</a>':forgot||reset?'<a href="#login">Back to sign in</a>':'<a href="#signup">Create an account</a><a href="#forgot-password">Forgot password?</a>'}</div></div><p class="terms-footnote">Account access is real. The payment gateway and all transfers are test simulations. Never enter real bank, card, or OTP details.</p></div>`}
function rules(g){return `<ol class="rules-list"><li>Contribute <b>${money(g.amount)} every month for ${g.capacity} rounds</b>, including after receiving your payout.</li><li>One member receives the equal <b>${money(g.amount*g.capacity)}</b> pool each round, in the approved membership order.</li><li><b>Interest: 0%. Platform fee: ₹0. Late-payment charge: ₹0.</b> No bidding, discounts or investment returns.</li><li>Payout release waits for every member’s successful contribution. A failed test payment adds no money or late fees.</li><li>Membership and payout order are locked when the circle starts. The organizer may pause a circle to resolve an issue.</li><li>Payments and payouts currently use a <b>fake gateway</b>. No real funds are charged, held, invested or transferred.</li></ol>`}
function circleCard(g){const mine=own(g);return `<article class="group-card"><div class="group-head"><span class="group-symbol">◎</span><div class="group-title"><h3>${esc(g.name)}</h3><p>${esc(g.description)}</p></div>${badge(g.status)}</div><div class="group-details"><div><small>Monthly contribution</small><strong>${money(g.amount)} <span>/ month</span></strong></div><div><small>Monthly pool</small><strong>${money(g.amount*g.capacity)}</strong></div><div><small>Commitment</small><strong>${g.capacity} <span>months</span></strong></div></div><div class="progress-label"><span>${g.status==='forming'?g.memberCount+' / '+g.capacity+' members':'Circle progress'}</span><span>${g.status==='forming'?(g.visibility==='private'?'Private circle':'Open circle'):g.round+' / '+g.capacity+' payouts'}</span></div><div class="progress"><div style="width:${(g.status==='forming'?g.memberCount:g.round)/g.capacity*100}%"></div></div><div class="group-foot"><small class="muted mini">${mine?'Your payout position: #'+mine.position:'Organized by '+esc(g.organizerName)}</small><a class="text-btn" href="#circle/${g.id}">${mine?'View circle':'Explore circle'} →</a></div></article>`}
function eventItem(e){return `<div class="audit-item"><span class="audit-icon">${e.type.includes('failed')?'!':e.type.includes('payout')?'↗':e.type.includes('payment.succeeded')?'✓':'◎'}</span><div><h4>${esc(e.title)}</h4><p>${esc(e.detail)}</p><time>${day(e.at)} · ${new Date(e.at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})} IST${e.circleName?' · '+esc(e.circleName):''}</time></div></div>`}
function overview(){const memberCircles=circles.filter(g=>!g.preview&&g.status!=='deleted'),active=memberCircles.filter(g=>['active','paused'].includes(g.status)),next=active.find(g=>g.status==='active'&&!paid(g).some(p=>p.userId===me.id));const tx=transactions(),total=tx.filter(p=>p.type==='Contribution'&&p.status==='succeeded').reduce((a,p)=>a+p.amount,0),upcoming=active.find(g=>own(g)?.position>g.round);return `<div class="workspace-team"><b>Project team</b><span>Shehzeen Fatima · Shaik Asefa · maryam Mohd · nabeehunnisa</span></div>${me?.demo?'<div class="mode-note"><b>Shared demo account:</b> actions and records are visible to other visitors using this login. Use fake information only.</div>':''}<div class="workspace-payment-link"><div><b>Contributions & prepayments</b><p>Open the payment centre to pay or check when payments become available.</p></div><a class="primary" href="#payments">Make a payment →</a></div><div class="hero"><section class="welcome-card"><div class="welcome-text"><span class="pill">✧ SAVE WITH PURPOSE</span><h2>Small contributions.<br>Meaningful possibilities.</h2><p>Create a circle, invite your community, and turn regular commitments into a shared milestone.</p><a class="text-btn" href="#principles">How interest-free circles work →</a></div><div class="plant-art" aria-hidden="true"><div class="orbit"></div><div class="stem"></div><div class="leaf"></div><div class="leaf two"></div><div class="leaf three"></div><div class="pot"></div><div class="coin">✦</div></div></section><section class="next-card"><div class="card-top"><span class="label">Your next contribution</span>${badge(next?'pending':'completed')}</div><h2>${next?money(next.amount):'A fresh start.'}</h2><p>${next?esc(next.name):memberCircles.length?'No contribution is waiting in an active circle.':'Your first circle is waiting to happen.'}</p><div class="due">${next?'Due '+day(due(next.startDate,next.round)):'A little consistency goes a long way.'}</div><button class="primary" ${next?`data-checkout="${next.id}"`:'data-action="create"'}>${next?'Contribute through test checkout':'Create a circle'} →</button></section></div><div class="stats">${[['Total contributed',money(total),'Successful test contributions','↗'],['Active circles',active.length,'Shared savings commitments','◎'],['Upcoming pool',upcoming?money(upcoming.amount*upcoming.capacity):'—',upcoming?'Your turn: '+day(due(upcoming.startDate,own(upcoming).position-1)):'Join or create a circle to begin','▤'],['Payouts received',tx.filter(p=>p.type==='Payout'&&p.status==='succeeded').length,'Completed test disbursements','✓']].map(a=>`<article class="stat"><div class="stat-top">${a[0]}<span class="stat-icon">${a[3]}</span></div><strong>${a[1]}</strong><small>${a[2]}</small></article>`).join('')}</div><div class="lower-grid"><section><div class="section-title"><h2>Your circles <span>${memberCircles.length}</span></h2><a class="text-btn" href="#circles">View all →</a></div><div class="group-list">${memberCircles.slice(0,2).map(circleCard).join('')||empty('Your next chapter starts here.','Create a circle with your community, or accept an invitation from someone you know.','Find a circle','#explore')}</div></section><section><div class="section-title"><h2>Recent activity</h2><a class="text-btn" href="#notifications">View all →</a></div><div class="activity-card">${activity().slice(0,4).map(eventItem).join('')||'<div class="notifications-empty">Your circle updates will appear here.</div>'}</div><div class="bottom-banner"><span>✧</span><div><b>A fair turn for everyone.</b><p>No bidding, interest, or late-payment profit.</p></div><a class="text-btn" href="#principles">Learn more →</a></div></section></div>`}
function circlesView(){const mine=circles.filter(g=>!g.preview&&g.status!=='deleted'),requests=circles.filter(g=>g.preview&&g.myApplication);return `<div class="search-row"><input type="search" id="circle-search" aria-label="Search your circles" placeholder="Search your circles…" value="${esc(searchText)}"></div><div class="view-grid" id="circle-results">${mine.filter(g=>g.name.toLowerCase().includes(searchText.toLowerCase())).map(circleCard).join('')||empty('Make your first shared commitment.','Create your own circle or join one through an invitation link.','Create a circle','create')}</div>${requests.length?'<div class="section-title" style="margin-top:28px"><h2>Your membership requests</h2></div>'+requests.map(g=>`<div class="application-card"><div><h4>${esc(g.name)}</h4><p>${g.myApplication.status==='pending'?'Waiting for organizer approval.':g.myApplication.status==='rejected'?'The organizer declined this request.':'Your request was approved.'}</p></div>${badge(g.myApplication.status)}</div>`).join(''):''}`}
function exploreView(data){return `<div class="panel" style="margin-bottom:25px"><h3>Have a private invitation?</h3><p>Paste the complete invitation link or code shared by your organizer.</p><form class="join-code" id="join-code-form"><input id="join-code" required aria-label="Invitation link or code" placeholder="Paste your invitation link here" autocomplete="off"><button class="primary">Open invitation →</button></form></div><div class="section-title"><h2>Open circles</h2><span class="label">Review the agreement before joining</span></div><div class="view-grid">${data.circles.map(circleCard).join('')||empty('No open circles right now.','Create an open circle, or ask your organizer for a private invitation.','Create a circle','create')}</div>`}
function memberList(g,admin=false){return g.members.map(m=>{const success=paid(g).some(p=>p.userId===m.userId);return `<div class="member-row"><span class="avatar">${esc(initials(m.name))}</span><div><b>${esc(m.name)}${m.userId===me.id?'<span class="own-label">YOU</span>':''}</b><small>Turn #${m.position}${m.userId===g.organizerId?' · Organizer':''}</small></div><div class="right">${g.status==='forming'?badge('approved'):g.status==='completed'?badge('completed'):badge(success?'succeeded':'pending')}</div></div>`}).join('')}
function requestsView(g){const apps=g.applications.filter(a=>a.status==='pending');return `<h3>Membership requests</h3>${apps.map(a=>`<div class="request-row"><span class="avatar">${esc(initials(a.name))}</span><div><b>${esc(a.name)}</b><small>Agreement accepted · ${day(a.at)}</small></div><div class="action-row"><button class="secondary" data-review="${g.id}:${a.id}:approve" ${g.memberCount>=g.capacity?'disabled':''}>Approve</button><button class="text-btn" data-review="${g.id}:${a.id}:reject">Decline</button></div></div>`).join('')||'<p>No pending requests. Share an invitation link to welcome members.</p>'}`}
function scheduleTable(g){return `<div class="table-wrap"><table><thead><tr><th>Round</th><th>Planned due date</th><th>Recipient</th><th>Pool (test)</th><th>Status</th></tr></thead><tbody>${Array.from({length:g.capacity},(_,i)=>{const m=g.members.find(m=>m.position===i+1),done=g.payouts.find(p=>p.round===i&&p.status==='succeeded');return `<tr><td>${String(i+1).padStart(2,'0')}</td><td>${day(due(g.startDate,i))}</td><td>${m?esc(m.name):'Awaiting member'}</td><td>${money(g.amount*g.capacity)}</td><td>${done?badge('completed'):i===g.round&&['active','paused'].includes(g.status)?'<span class="pill warn">Current round</span>':'<span class="label">Scheduled</span>'}</td></tr>`}).join('')}</tbody></table></div><p class="screen-only-note">These are planned dates. A test payout is released only after every member’s contribution succeeds.</p>`}
function detailView(g){if(g.preview){return `<div class="detail-hero"><div>${badge(g.status)}<h2>${esc(g.name)}</h2><p>${esc(g.description)}</p><p>Organized by ${esc(g.organizerName)} · ${g.memberCount}/${g.capacity} members</p></div><div class="pool"><small>MONTHLY POOL · TEST</small><strong>${money(g.amount*g.capacity)}</strong><small>${money(g.amount)} per member / month</small></div></div><div class="split"><div class="panel"><h3>Understand your shared commitment</h3>${rules(g)}</div><div class="panel"><h3>${g.myApplication?.status==='pending'?'Your request is with the organizer.':'A place for your next milestone.'}</h3><p>${g.myApplication?.status==='pending'?'You’ll see this circle in My circles when your membership is approved. Refresh to check for updates.':'Accept the agreement to request the next available membership position. The organizer reviews every request.'}</p>${g.myApplication?.status==='pending'?badge('pending'):g.memberCount<g.capacity?`<button class="primary" data-join="${g.id}">Request to join →</button>`:badge('Circle full')}</div></div>`}
 const organizer=g.role==='organizer',my=own(g),collected=paid(g),alreadyPaid=collected.some(p=>p.userId===me.id),nextRecipient=g.members.find(m=>m.position===g.round+1);return `<div class="section-title"><a class="text-btn" href="#circles">← Back to your circles</a><span class="showcase-tag">${g.visibility==='private'?'Private circle':'Open circle'} · Fixed order · 0% interest</span></div><div class="detail-hero"><div>${badge(g.status)}<h2>${esc(g.name)}</h2><p>${esc(g.description)}</p><p>Organized by ${esc(g.organizerName)} · ${g.memberCount}/${g.capacity} members · Starts ${day(g.startDate)}</p></div><div class="pool"><small>MONTHLY POOL · TEST</small><strong>${money(g.amount*g.capacity)}</strong><small>${money(g.amount)} per member / month</small></div></div>${g.status==='forming'?organizer?`<div class="notice"><p><b>${g.capacity-g.memberCount} spot${g.capacity-g.memberCount===1?'':'s'} available.</b> Invite members to create their own accounts and accept your circle’s agreement.</p><div class="circle-actions"><button class="primary" data-invite="${g.id}">＋ Add / invite member</button><button class="secondary" data-start="${g.id}" ${g.memberCount===g.capacity?'':'disabled'}>Start circle →</button></div></div>`:notice('This circle is forming. The organizer will start it when every membership spot is filled.'):notice('<b>Membership is locked.</b> The approved payout order stays fixed for the full rotation.')}${g.status==='paused'?`<div class="notice warn"><b>Circle paused</b><p>${esc(g.pauseReason)}</p></div>`:''}${g.status==='deleted'?notice('<b>This circle was deleted.</b> Payments and payouts are closed. Past transactions remain available in Payments.'):organizer?`<div class="circle-actions" style="margin:18px 0"><button class="text-btn" data-delete-circle="${g.id}">Delete circle</button></div>`:''}<div class="tabs">${[['overview','Overview'],['members','Members & requests'],['schedule','Payout schedule'],['agreement','Agreement'],['activity','Activity']].map(([id,label])=>`<button class="secondary ${detailTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>${detailTab==='members'?`<div class="split"><div class="panel"><h3>Fixed membership order</h3>${memberList(g)}</div><div class="panel">${organizer?requestsView(g):'<h3>Shared accountability</h3><p>Each approved member has one payout and continues contributing until the circle is complete.</p>'}</div></div>`:detailTab==='schedule'?scheduleTable(g):detailTab==='agreement'?`<div class="panel"><h3>Circle agreement · Version 1</h3>${rules(g)}</div>`:detailTab==='activity'?`<div class="panel">${g.events.map(eventItem).join('')}</div>`:`<div class="split"><div class="stack"><div class="panel"><h3>${g.status==='completed'?'A full circle, completed.':g.status==='forming'?'Getting your circle ready.':'Round '+(g.round+1)+' of '+g.capacity}</h3><p>${g.status==='forming'?'Share the invitation link and approve each member’s request. Every participant signs in using their own account.':g.status==='completed'?'Every member has received one equal test payout. Your full history remains available.':'The current scheduled recipient is '+esc(nextRecipient?.name||'the next member')+'. Contributions are collected through the fake payment gateway.'}</p><div class="funding-line"><span>${g.status==='forming'?'Membership confirmed':'Current round collected (test)'}</span><b>${g.status==='forming'?g.memberCount+' / '+g.capacity:money(collected.reduce((n,p)=>n+p.amount,0))+' / '+money(g.amount*g.capacity)}</b></div><div class="progress large"><div style="width:${(g.status==='forming'?g.memberCount:collected.length)/g.capacity*100}%"></div></div><div class="action-row">${g.status==='active'?`<button class="primary" data-checkout="${g.id}" ${alreadyPaid?'disabled':''}>${alreadyPaid?'✓ Your contribution is complete':'Contribute '+money(g.amount)+' (test) →'}</button>`:''}${g.status==='active'&&Array.from({length:g.capacity-g.round},(_,i)=>g.round+i).some(r=>!paid(g,r).some(p=>p.userId===me.id))?`<button class="secondary" data-prepay="${g.id}">Prepay a round →</button>`:''}${organizer&&g.status==='active'?`<button class="secondary" data-payout="${g.id}" ${funded(g)?'':'disabled'}>Release test pool →</button><button class="text-btn" data-pause="${g.id}">Pause circle</button>`:''}${organizer&&g.status==='paused'?`<button class="primary" data-resume="${g.id}">Resume circle</button>`:''}</div>${g.status==='active'&&!funded(g)?'<p class="hint">Payout release stays locked until every member’s contribution succeeds.</p>':''}</div><div class="panel"><h3>${g.status==='forming'?'Your members':'This round’s contributions'}</h3>${memberList(g)}</div></div><div class="stack"><div class="panel"><h3>Your commitment, at a glance</h3><div class="summary-row"><span>Monthly contribution</span><b>${money(g.amount)}</b></div><div class="summary-row"><span>Total commitment</span><b>${money(g.amount*g.capacity)}</b></div><div class="summary-row"><span>Duration</span><b>${g.capacity} monthly rounds</b></div><div class="summary-row"><span>Interest / platform fee</span><b>0% / ₹0</b></div><div class="summary-row"><span>Your payout position</span><b>#${my.position}</b></div><div class="summary-row"><span>Your planned turn</span><b>${day(due(g.startDate,my.position-1))}</b></div><p class="hint">Receiving a payout does not end your contribution commitment. All transfers currently use test funds.</p></div><div class="panel"><h3>Fair turns. Clear records.</h3><p>No auctions, hidden deductions or interest. See every round in the payout schedule.</p><button class="text-btn" data-tab="schedule">View the full rotation →</button></div></div></div>`}`}
function organizerView(){const owned=circles.filter(g=>g.role==='organizer'&&g.status!=='deleted');return owned.length?owned.map(g=>`<div class="panel" style="margin-bottom:22px"><div class="section-title"><h2>${esc(g.name)}</h2>${badge(g.status)}</div><div class="split"><div><p>${g.status==='forming'?g.memberCount+' / '+g.capacity+' membership spots filled':g.status==='completed'?'Every member has received a test payout.':'Round '+(g.round+1)+' / '+g.capacity+' · '+paid(g).length+' / '+g.capacity+' contributions'}</p>${memberList(g)}</div><div>${g.status==='forming'?requestsView(g):`<h3>Pool controls</h3><div class="summary-row"><span>Collected this round</span><b>${money(paid(g).reduce((n,p)=>n+p.amount,0))}</b></div><div class="summary-row"><span>Required pool</span><b>${money(g.amount*g.capacity)}</b></div><div class="summary-row"><span>Recipient</span><b>${esc(g.members.find(m=>m.position===g.round+1)?.name||'All payouts complete')}</b></div>`}<div class="action-row">${g.status==='forming'?`<button class="primary" data-invite="${g.id}">＋ Add / invite member</button><button class="secondary" data-start="${g.id}" ${g.memberCount===g.capacity?'':'disabled'}>Start circle</button>`:g.status==='active'?`<button class="primary" data-payout="${g.id}" ${funded(g)?'':'disabled'}>Release test pool</button><button class="secondary" data-pause="${g.id}">Pause circle</button>`:g.status==='paused'?`<button class="primary" data-resume="${g.id}">Resume circle</button>`:''}</div><p><a class="text-btn" href="#circle/${g.id}">Open full circle →</a></p></div></div></div>`).join(''):empty('Your organizer desk is ready.','Create a circle to invite members and manage the full savings rotation.','Create a circle','create')}
function paymentOptions(){const mine=circles.filter(g=>!g.preview&&g.status!=='deleted');return `<section class="panel payment-options"><h2>Make a test payment</h2><p>Pay your current contribution or prepay a future round. No real money is charged.</p>${mine.map(g=>{const unpaid=Array.from({length:g.capacity-g.round},(_,i)=>g.round+i).some(r=>!paid(g,r).some(p=>p.userId===me.id)),currentPaid=paid(g).some(p=>p.userId===me.id);return `<div class="payment-option-row"><div><h3>${esc(g.name)}</h3><p>${money(g.amount)} per round · ${g.status==='forming'?`Payments unlock after all ${g.capacity} members join and the organizer starts the circle (${g.memberCount}/${g.capacity} joined).`:g.status==='paused'?'Payments are paused. The organizer must resume the circle.':g.status==='completed'?'All rounds completed. Receipts remain available.':currentPaid?'Current round paid. You can prepay another unpaid round.':'Current contribution is ready to pay.'}</p></div><div class="action-row">${g.status==='active'?`<button class="primary" data-checkout="${g.id}" ${currentPaid?'disabled':''}>${currentPaid?'Current round paid':'Pay '+money(g.amount)+' (test)'}</button><button class="secondary" data-prepay="${g.id}" ${unpaid?'':'disabled'}>Prepay a round</button>`:`<button class="secondary" disabled>Payment ${g.status==='forming'?'not open':g.status==='paused'?'paused':'complete'}</button>`}<a class="text-btn" href="#circle/${g.id}">Open circle →</a></div></div>`}).join('')||'<p>Join or create a circle to make a payment. Payments open once the organizer activates the full circle.</p><a class="primary" href="#circles">View your circles →</a>'}</section>`}
function paymentsView(){return `${paymentOptions()}<div class="mode-note"><b>Test mode:</b> these are simulated transactions. No real card, bank account or UPI service is charged.</div><div class="section-title"><h2>Your transaction history</h2><button class="secondary" data-action="export">↓ Export CSV</button></div><div class="table-wrap payment-table"><table><thead><tr><th>Date</th><th>Circle / reference</th><th>Type</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${transactions().map(t=>`<tr><td>${day(t.createdAt)}</td><td>${esc(t.circleName)}<small class="reference-cell muted" style="display:block;margin-top:6px">${esc(t.reference)}</small></td><td>${t.type}</td><td>${money(t.amount)}</td><td>${badge(t.status)}</td><td>${t.status==='succeeded'?`<a class="text-btn" href="#receipt/${t.circleId}/${t.id}">Receipt →</a>`:t.type==='Contribution'?`<a class="text-btn" href="#checkout/${t.circleId}/${t.id}">${t.status==='pending'?'Resume checkout':'View attempt'} →</a>`:'No funds moved'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Your first test payment will appear here.</td></tr>'}</tbody></table></div>`}
function scheduleView(){const mine=circles.filter(g=>!g.preview&&g.status!=='deleted');return mine.length?`<div class="toolbar-group"><label for="schedule-circle">Choose a circle</label><select id="schedule-circle">${mine.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select><button class="secondary" data-action="print">Print schedule</button></div><div id="schedule-content" style="margin-top:20px">${scheduleTable(mine[0])}</div>`:empty('Your schedule is waiting.','Join a circle to see your fixed contribution and payout dates.','Find a circle','#explore')}
function accountView(){return `<div class="account-grid"><div class="panel"><div class="identity-strip"><span class="avatar">${esc(initials(me.name))}</span><div><h3>${esc(me.name)}</h3><small>Your signed-in account</small></div></div><form id="profile-form" class="account-form"><label for="profile-name-input">Display name</label><input id="profile-name-input" value="${esc(me.name)}" minlength="2" maxlength="60" required autocomplete="name"><label for="profile-email">Email address</label><input id="profile-email" value="${esc(me.email)}" disabled><div class="inline-error" role="alert"></div><button class="primary">Save profile</button></form><p class="invite-help">Your name on previously accepted circle agreements stays in their activity records. New requests use your current account name.</p></div><div class="stack"><div class="panel"><h3>Account security</h3><p>Account access is managed by Netlify Identity. Sign in on another device to access your saved circles, memberships and payment records.</p><div class="action-row"><a class="secondary" href="#forgot-password">Reset password</a><button class="secondary" data-action="logout">Sign out</button></div></div><div class="panel"><h3>Payments stay in test mode</h3><p>The gateway simulates payments and payouts. Never enter a real card number, UPI PIN, bank password, or bank OTP.</p><p>Identity verification for regulated financial services is not performed by this application.</p></div></div></div>`}
function principlesView(){return `${!me?'<div class="public-principles"><h1>Good intentions. Clear commitments.</h1>':''}<div class="principle-banner"><b>A fair rotation, grounded in shared responsibility.</b><br>Halal Chit Fund uses an interest-free ROSCA model. Formal Shariah certification is not claimed. All payments and payouts currently use a clearly marked fake gateway.</div><div class="principle-cards">${[['01','No interest','Every member contributes the same amount and receives one equal pool. There is no interest, investment profit, or additional payment for an earlier turn.'],['02','No auctions or bidding','Payout order follows the approved membership positions. The circle’s membership and order are locked at activation.'],['03','Clear agreement','Contribution, duration, order, zero fees and missed-payment rules are displayed and accepted before membership approval.'],['04','No late-payment profit','A missing contribution holds the payout. No late fee or added interest increases the member’s obligation.'],['05','Shared accountability','Each recipient continues contributing after their payout. The organizer and members can review payment status and activity.'],['06','Transparent test payments','This version does not collect, hold or invest real funds. The gateway demonstrates collection, failures, retries and payouts with simulated money.']].map(a=>`<article class="principle-card"><span class="number">${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p></article>`).join('')}</div><div class="panel"><h3>Understand the commitment</h3><p>A pooled payout is not a financial return. Early recipients gain earlier access while later recipients use the rotation as a savings commitment. Members can default; digital records do not guarantee future contributions.</p><p>Any future real-money version requires qualified Shariah and jurisdiction-specific legal review, approved collection and custody arrangements, real identity checks, and operational safeguards. None of those approvals are implied by an account or a test payment.</p></div>${!me?'</div>':''}`}
function checkoutView(data){const{circle:g,order:o}=data;if(checkoutChoice.orderId!==o.id){checkoutChoice={method:'test_card',scenario:'approved',orderId:o.id};checkoutStep='payment'}if(o.status!=='pending')return checkoutResult(data);const method=checkoutChoice.method;return `<div class="gateway-wrap"><div class="gateway-head"><div><a class="text-btn" href="#circle/${g.id}">← Back to circle</a><h1>Your contribution, one step closer.</h1></div><span class="pill warn">FAKE GATEWAY · TEST MODE</span></div><div class="gateway-grid"><section class="order-summary"><span class="label">CONTRIBUTION SUMMARY</span><div class="amount">${money(o.amount)}</div><p>${esc(g.name)} · Round ${o.round+1}</p><div class="summary-row"><span>Paying member</span><b>${esc(me.name)}</b></div><div class="summary-row"><span>Contribution</span><b>${money(o.amount)}</b></div><div class="summary-row"><span>Platform fee / interest</span><b>₹0 / 0%</b></div><div class="summary-row"><span>Currency</span><b>INR · Test funds</b></div><div class="reference">${esc(o.reference)}</div><p>Checkout expires ${new Date(o.expiresAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})} IST. The amount is set by your circle’s agreement.</p></section><section class="gateway-card">${checkoutStep==='otp'?`<h2>Confirm your test payment.</h2><p>This is a simulated authorization step. Use the code displayed below.</p><div class="otp-display">123456</div><form id="otp-form" class="gateway-form"><label for="test-otp">Test OTP — use 123456</label><input id="test-otp" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="off" required placeholder="Enter the displayed code"><p class="hint">Never enter an OTP from your bank. This code does not authorize a real transaction.</p><div class="inline-error" role="alert"></div><button class="primary">Confirm ${money(o.amount)} test payment →</button></form><button class="text-btn" data-action="gateway-back">← Change test payment method</button>`:`<h2>Choose a test payment method.</h2><p>Try a complete payment flow without connecting a bank account.</p><div class="payment-methods"><button class="${method==='test_card'?'selected':''}" data-method="test_card"><span>▣</span>Test card</button><button class="${method==='test_upi'?'selected':''}" data-method="test_upi"><span>⇄</span>Test UPI</button></div><form id="checkout-form" class="gateway-form">${method==='test_card'?'<label for="test-card">Test card number (fixed fixture)</label><input id="test-card" readonly value="4242 4242 4242 4242" tabindex="-1"><div class="form-grid"><div><label for="test-expiry">Test expiry</label><input id="test-expiry" readonly value="12 / 30" tabindex="-1"></div><div><label for="test-cvv">Test CVV</label><input id="test-cvv" readonly value="123" tabindex="-1"></div></div>':'<label for="test-upi">Test UPI account (fixed fixture)</label><input id="test-upi" readonly value="member@hcf.test" tabindex="-1">'}<label for="gateway-scenario">Test gateway response</label><select id="gateway-scenario"><option value="approved" ${checkoutChoice.scenario==='approved'?'selected':''}>Approve payment — successful contribution</option><option value="declined" ${checkoutChoice.scenario==='declined'?'selected':''}>Decline payment — demonstrate retry</option></select><p class="hint">These fixed test details cannot charge a real card or UPI account.</p><div class="inline-error" role="alert"></div><button class="primary">Continue with ${money(o.amount)} (test) →</button></form>`}<div class="test-banner"><b>No real money is charged.</b> This gateway is an internal simulator. It does not contact a bank, card network, UPI provider or escrow service.</div><button class="text-btn" data-cancel-order="${g.id}:${o.id}">Cancel this test payment</button></section></div><div class="gateway-foot">Your contribution follows the circle’s agreed amount. This is a test payment; no real money will move.</div></div>`}
function checkoutResult({circle:g,order:o}){const success=o.status==='succeeded',labels={failed:'Test payment declined.',cancelled:'Test payment cancelled.',expired:'Your test checkout expired.'};return `<div class="gateway-wrap"><div class="panel gateway-status"><span class="status-symbol ${success?'':'failed'}">${success?'✓':'!'}</span><span class="pill ${success?'good':'warn'}">TEST TRANSACTION · NO REAL MONEY</span><h2>${success?'Your contribution is recorded.':labels[o.status]||'Payment update'}</h2><div class="amount">${money(o.amount)}</div><p>${success?'Your successful test contribution now counts toward '+esc(g.name)+'. The pool can be released only when every member has contributed.':o.reason?esc(o.reason):'No funds were recorded. You can start a new test checkout without a fee.'}</p><div class="reference">${esc(o.reference)}</div><div class="action-row">${success?`<a class="primary" href="#receipt/${g.id}/${o.id}">View receipt →</a>`:`<button class="primary" data-checkout="${g.id}" data-round="${o.round}">Try a new test payment →</button>`}<a class="secondary" href="#circle/${g.id}">Back to circle</a></div></div></div>`}
function receiptView(data){const t=data.transaction;return `<div class="receipt-page"><div class="action-row" style="margin:0 0 18px"><a class="text-btn" href="#payments">← Back to payments</a></div><div class="panel"><div class="receipt-brand">◌ &nbsp;Halal Chit Fund<span class="brand-dot">.</span></div><span class="pill good">COMPLETED TEST ${t.type==='payout'?'PAYOUT':'CONTRIBUTION'}</span><h2>${money(t.amount)}</h2><p>${esc(t.reference)}</p><div class="summary-row"><span>Member</span><b>${esc(data.accountName)}</b></div><div class="summary-row"><span>Circle</span><b>${esc(data.circle.name)}</b></div><div class="summary-row"><span>Round</span><b>${t.round+1}</b></div><div class="summary-row"><span>Date</span><b>${day(t.completedAt||t.createdAt)}</b></div><div class="summary-row"><span>Method</span><b>${t.type==='payout'?'Simulated disbursement':t.method==='test_upi'?'Test UPI':'Test card'}</b></div><div class="summary-row"><span>Currency / mode</span><b>INR / Test funds</b></div><div class="summary-row"><span>Interest / fee</span><b>0% / ₹0</b></div><div class="mode-note"><b>Simulation receipt.</b> No real funds were charged or transferred. This is an application record, not a bank or tax receipt.</div></div><div class="action-row"><button class="primary" data-action="print">Print / save receipt →</button><a class="secondary" href="#circle/${data.circle.id}">Open circle</a></div></div>`}
function renderCurrent(key,data){if(!me){$('#content').innerHTML=['login','signup','forgot-password','reset-password'].includes(key)?authView(key):key==='principles'?principlesView():landing();bindForms();return}let html='';if(key==='overview')html=overview();else if(key==='circles')html=circlesView();else if(key==='explore')html=exploreView(data);else if(key==='circle'||key==='join')html=detailView(data.circle);else if(key==='organizer')html=organizerView();else if(key==='payments')html=paymentsView();else if(key==='schedule')html=scheduleView();else if(key==='account')html=accountView();else if(key==='notifications')html=`<div class="panel">${activity().map(eventItem).join('')||'<div class="notifications-empty">No updates yet. Your circle’s activity will appear here.</div>'}</div>`;else if(key==='principles')html=principlesView();else if(key==='checkout')html=checkoutView(data);else if(key==='receipt')html=receiptView(data);else html=overview();$('#content').innerHTML=html;bindForms()}
async function navigate(){const epoch=++navEpoch,r=route(),parts=r.split('/'),key=parts[0];layout(key);if(!me){if(['circle','join','checkout'].includes(key)){sessionStorage.setItem('hcf-return-to','#'+r);location.hash='login';return}renderCurrent(key);return}if(['login','signup','forgot-password','reset-password'].includes(key)){if(key!=='forgot-password'&&key!=='reset-password'){location.hash='overview';return}layout(key,'public');$('#content').innerHTML=authView(key);bindForms();return}try{let data={};if(key==='explore')data=await api('/explore');if(key==='circle')data=await api('/circles/'+encodeURIComponent(parts[1]));if(key==='join')data=await api('/invitations/'+encodeURIComponent(parts.slice(1).join('/')));if(key==='checkout')data=await api('/circles/'+encodeURIComponent(parts[1])+'/checkout/'+encodeURIComponent(parts[2]));if(key==='receipt')data=await api('/circles/'+encodeURIComponent(parts[1])+'/receipts/'+encodeURIComponent(parts[2]));if(epoch!==navEpoch)return;pageData=data;renderCurrent(key,data);if(key==='notifications'&&activity().some(e=>!me.notificationsReadAt||e.at>me.notificationsReadAt)){await api('/notifications/read',{});me.notificationsReadAt=new Date().toISOString();layout(key)}}catch(e){if(epoch!==navEpoch)return;if(e.status===401){me=null;sessionStorage.setItem('hcf-return-to','#'+r);location.hash='login';toast('Please sign in to continue.');return}$('#content').innerHTML=empty('We couldn’t open this page.',e.message,'Refresh saved records','refresh')}}
async function afterAuth(){await sync();const saved=sessionStorage.getItem('hcf-return-to');sessionStorage.removeItem('hcf-return-to');const next=saved&&/^#(join|circle|checkout)\//.test(saved)?saved:'#overview';if(location.hash===next)await navigate();else location.hash=next;toast('You’re signed in. Welcome to your circle.')}
function bindForms(){
 const f=$('#auth-form');if(f)f.onsubmit=e=>{e.preventDefault();run(f,async()=>{const kind=f.dataset.kind,email=$('#auth-email')?.value,password=$('#auth-password')?.value;if(kind==='signup'){const d=await api('/auth/signup',{name:$('#auth-name').value,email,password,accepted:$('#auth-terms').checked});if(d.requiresConfirmation){$('#content').innerHTML=authView('login',d.message);bindForms()}else await afterAuth()}else if(kind==='login'){await api('/auth/login',{email,password});await afterAuth()}else if(kind==='forgot-password'){const d=await api('/auth/recover',{email});f.innerHTML=`<div class="auth-message">${esc(d.message)}</div>`}else if(kind==='reset-password'){if(!recoveryToken)throw new Error('Open the complete password reset link from your email.');await api('/auth/reset',{token:recoveryToken,password});recoveryToken=null;await afterAuth()}})};
 const profile=$('#profile-form');if(profile)profile.onsubmit=e=>{e.preventDefault();run(profile,async()=>{const d=await api('/profile',{name:$('#profile-name-input').value});me=d.user;await navigate();toast('Your profile is saved.')})};
 const joinForm=$('#join-code-form');if(joinForm)joinForm.onsubmit=e=>{e.preventDefault();let value=$('#join-code').value.trim();try{if(value.includes('://'))value=new URL(value).hash.replace(/^#join\//,'');else value=value.replace(/^#?join\//,'');if(!/^[a-f\d-]{36}\.[a-f\d]{32}$/i.test(value))throw new Error();location.hash='join/'+value}catch{toast('Paste the complete invitation link or code shared by your organizer.')}};
 const search=$('#circle-search');if(search)search.oninput=()=>{searchText=search.value;$('#circle-results').innerHTML=circles.filter(g=>!g.preview&&g.name.toLowerCase().includes(searchText.toLowerCase())).map(circleCard).join('')||empty('No circles match.','Try a different name.','','')};
 const schedule=$('#schedule-circle');if(schedule)schedule.onchange=()=>{$('#schedule-content').innerHTML=scheduleTable(circles.find(g=>g.id===schedule.value))};
 const checkout=$('#checkout-form');if(checkout)checkout.onsubmit=e=>{e.preventDefault();checkoutChoice.scenario=$('#gateway-scenario').value;checkoutStep='otp';renderCurrent('checkout',pageData);$('#test-otp').focus()};
 const otp=$('#otp-form');if(otp)otp.onsubmit=e=>{e.preventDefault();const code=$('#test-otp').value;run(otp,async()=>{const{circle:g,order:o}=pageData;await api('/circles/'+g.id+'/confirm',{orderId:o.id,method:checkoutChoice.method,scenario:checkoutChoice.scenario,otp:code});await sync();await navigate()})};
}
function createCircleModal(){if(!me){location.hash='signup';return}const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});modal('Start something good.',`<p>Create a circle and invite members to join from their own accounts.</p><form id="create-form"><label for="circle-name">Circle name</label><input id="circle-name" minlength="3" maxlength="60" required placeholder="e.g. Community milestones"><label for="circle-description">Shared purpose</label><textarea id="circle-description" minlength="5" maxlength="220" required placeholder="What are you saving toward?"></textarea><div class="form-grid"><div><label for="circle-amount">Monthly contribution (₹)</label><input id="circle-amount" type="number" min="100" max="100000" step="1" value="2000" required></div><div><label for="circle-capacity">Members / monthly rounds</label><select id="circle-capacity">${Array.from({length:10},(_,i)=>`<option value="${i+3}" ${i===3?'selected':''}>${i+3} members · ${i+3} months</option>`).join('')}</select></div></div><label for="circle-date">First contribution due date</label><input id="circle-date" type="date" min="${today}" value="${today}" required><label for="circle-visibility">Who can find this circle?</label><select id="circle-visibility"><option value="private">Private — invitation link required</option><option value="public">Open — signed-in users can request to join</option></select><p class="note">Equal monthly contributions. Fixed approval order. 0% interest. ₹0 platform or late fees. Payments and payouts are simulated.</p><label class="check"><input type="checkbox" id="create-terms" required><span>I am an adult and accept every round’s contribution, including after my payout. I understand that funding is not guaranteed and all current payments are test simulations.</span></label><button class="primary">Create circle →</button></form>`);const form=$('#create-form'),operationId=crypto.randomUUID();form.onsubmit=e=>{e.preventDefault();const values={name:$('#circle-name').value,description:$('#circle-description').value,amount:Number($('#circle-amount').value)*100,capacity:Number($('#circle-capacity').value),startDate:$('#circle-date').value,visibility:$('#circle-visibility').value,accepted:$('#create-terms').checked,adult:$('#create-terms').checked,operationId};run(form,async()=>{const d=await api('/circles',values);close();await sync();detailTab='members';location.hash='circle/'+d.circle.id;toast('Your circle is ready. Invite your first member.')})}}
function inviteModal(g){const link=location.origin+'/#join/'+g.inviteLinkToken;modal('Welcome someone to your circle.',`<p>Share this private invitation for <b>${esc(g.name)}</b>. Your member signs in with their own account, accepts the agreement, and sends a request for you to approve.</p><label for="invite-link">Invitation link</label><div class="copy-box"><input id="invite-link" readonly value="${esc(link)}"><button class="secondary" id="copy-invite">Copy link</button></div><div class="share-link-note"><b>No email is sent automatically.</b> Share this link through your preferred channel. Member requests appear in this circle’s Members & requests tab and your Organizer desk.</div><p class="invite-help">${g.memberCount} / ${g.capacity} members confirmed. Approved members receive the next available payout position. Membership locks when the circle starts.</p><button class="primary" id="view-requests">View membership requests →</button>`);$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Invitation link copied.')}catch{$('#invite-link').select();toast('Select and copy the invitation link.')}};$('#view-requests').onclick=()=>{close();detailTab='members';if(route()==='circle/'+g.id)renderCurrent('circle',{circle:g});else location.hash='circle/'+g.id}}
function joinModal(g){const token=pageData?.inviteToken;modal('A shared commitment.',`<p>Request a place in <b>${esc(g.name)}</b>. The organizer assigns your payout position when approving your request.</p>${rules(g)}<form id="membership-form"><label class="check"><input type="checkbox" id="membership-terms" required><span>I am an adult and accept the full agreement, including all monthly contributions after receiving my own payout. I understand the current gateway uses test funds.</span></label><button class="primary">Accept & request membership →</button></form>`);const form=$('#membership-form'),operationId=crypto.randomUUID();form.onsubmit=e=>{e.preventDefault();run(form,async()=>{await api('/circles/'+g.id+'/join',{accepted:$('#membership-terms').checked,adult:$('#membership-terms').checked,inviteToken:token,operationId});close();await sync();location.hash='circle/'+g.id;await navigate();toast('Your request is awaiting organizer approval.')})}}
function startModal(g){modal('Ready to begin together?',`<p>Activate <b>${esc(g.name)}</b> with ${g.memberCount} confirmed members. Membership and payout order will be locked for all ${g.capacity} rounds.</p><p class="note">Every member accepted the contribution agreement. After starting, members can use the fake gateway to complete their contributions.</p><button class="primary" id="confirm-start">Activate circle →</button>`);$('#confirm-start').onclick=()=>run(null,async()=>{await api('/circles/'+g.id+'/start',{});await sync();await navigate();close();toast('Your circle is active.')})}
function payoutModal(g){const recipient=g.members.find(m=>m.position===g.round+1);modal('A fair turn, fulfilled.',`<p>Release the fully funded <b>test pool</b> to the fixed recipient.</p><div class="summary-row"><span>Recipient</span><b>${esc(recipient?.name)}</b></div><div class="summary-row"><span>Round</span><b>${g.round+1} of ${g.capacity}</b></div><div class="summary-row"><span>Test payout</span><b>${money(g.amount*g.capacity)}</b></div><form id="payout-form"><label for="payout-scenario">Fake payout gateway response</label><select id="payout-scenario"><option value="approved">Approve test payout</option><option value="declined">Decline test payout — keep this round</option></select><p class="note">This is not a bank transfer. A successful test payout advances one round; the recipient must keep contributing.</p><button class="primary">Confirm simulated payout →</button></form>`);const form=$('#payout-form'),operationId=crypto.randomUUID();form.onsubmit=e=>{e.preventDefault();const scenario=$('#payout-scenario').value;run(form,async()=>{await api('/circles/'+g.id+'/payout',{scenario,operationId});await sync();await navigate();close();toast(scenario==='approved'?'Test payout recorded. The circle has advanced.':'Test payout declined. The current pool remains unchanged.')})}}
function deleteCircleModal(g){modal('Delete this circle?',`<p>This closes <b>${esc(g.name)}</b> for every member and removes it from current circles. Pending checkouts are cancelled. Payment history, prepayments, payouts and receipts remain available; no test funds are refunded or erased.</p><form id="delete-circle-form"><label for="delete-circle-name">Type the exact circle name to confirm</label><input id="delete-circle-name" required autocomplete="off"><button class="primary">Confirm circle deletion</button></form>`);const form=$('#delete-circle-form'),operationId=crypto.randomUUID();form.onsubmit=e=>{e.preventDefault();const confirmName=$('#delete-circle-name').value;run(form,async()=>{await api('/circles/'+g.id+'/delete',{confirmName,operationId});await sync();close();location.hash='circles';await navigate();toast('Circle deleted. Payment history and receipts are preserved.')})}}
function csv(rows,name){const field=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"'};const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(field).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function action(name){if(name==='create')createCircleModal();if(name==='account')location.hash='account';if(name==='print')window.print();if(name==='refresh')run(null,async()=>{if(me)await sync();else{const d=await api('/me');me=d.user;if(me)await sync()}await navigate();toast('Saved records refreshed.')});if(name==='logout')run(null,async()=>{await api('/auth/logout',{});me=null;circles=[];close();location.hash='overview';await navigate();toast('You’re signed out.')});if(name==='gateway-back'){checkoutStep='payment';renderCurrent('checkout',pageData)}if(name==='export'){csv([['Reference','Date (IST)','Circle','Round','Type','Amount (INR)','Status','Mode'],...transactions().map(p=>[p.reference,day(p.createdAt),p.circleName,p.round+1,p.type,p.amount/100,p.status,'Test — no real funds'])],'halal-chit-fund-payments.csv');toast('Your transaction record is exported.')}}
async function groupById(id){if(pageData?.circle?.id===id)return pageData.circle;const found=circles.find(g=>g.id===id);if(found&&!found.preview)return found;return(await api('/circles/'+id)).circle}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b||b.disabled||busy)return;const d=b.dataset;try{if(d.demoEmail){$('#auth-email').value=d.demoEmail;$('#auth-password').value=demoAccounts.password;toast('Demo login filled. Press Sign in to continue.')}if(d.action)action(d.action);if(d.go)location.hash=d.go;if(d.tab){detailTab=d.tab;renderCurrent('circle',pageData)}if(d.invite)inviteModal(await groupById(d.invite));if(d.join)joinModal(await groupById(d.join));if(d.start)startModal(await groupById(d.start));if(d.payout)payoutModal(await groupById(d.payout));if(d.review){const[g,app,decision]=d.review.split(':');await run(null,async()=>{await api('/circles/'+g+'/review',{applicationId:app,decision});await sync();await navigate();toast(decision==='approve'?'Member approved. Their payout position is assigned.':'Membership request declined.')})}if(d.deleteCircle)deleteCircleModal(await groupById(d.deleteCircle));if(d.prepay){const g=await groupById(d.prepay);modal('Prepay a contribution',`<p>Choose a round to pay in advance. No fees or interest. Test funds only; payout order stays fixed.</p><form id="prepay-form"><label for="prepay-round">Contribution round</label><select id="prepay-round">${Array.from({length:g.capacity-g.round},(_,i)=>g.round+i).filter(r=>!paid(g,r).some(p=>p.userId===me.id)).map(r=>`<option value="${r}">Round ${r+1} · ${day(due(g.startDate,r))} · ${money(g.amount)}</option>`).join('')}</select><button class="primary">Continue to test checkout →</button></form>`);$('#prepay-form').onsubmit=e=>{e.preventDefault();const round=Number($('#prepay-round').value);run(null,async()=>{const data=await api('/circles/'+g.id+'/checkout',{round});close();location.hash='checkout/'+g.id+'/'+data.orderId})}}if(d.checkout)await run(null,async()=>{const data=await api('/circles/'+d.checkout+'/checkout',d.round===undefined?{}:{round:Number(d.round)});location.hash='checkout/'+d.checkout+'/'+data.orderId});if(d.method){checkoutChoice.method=d.method;renderCurrent('checkout',pageData)}if(d.cancelOrder){const[g,o]=d.cancelOrder.split(':');await run(null,async()=>{await api('/circles/'+g+'/cancel',{orderId:o});await sync();await navigate()})}if(d.pause){modal('A pause can protect your circle.',`<p>Pause contributions and payouts while you resolve a missed contribution or member concern. No fees or interest are added.</p><form id="pause-form"><label for="pause-reason">Reason visible to members</label><textarea id="pause-reason" minlength="5" maxlength="180" required></textarea><button class="primary">Pause circle</button></form>`);const form=$('#pause-form');form.onsubmit=ev=>{ev.preventDefault();const reason=$('#pause-reason').value;run(form,async()=>{await api('/circles/'+d.pause+'/pause',{reason});await sync();await navigate();close();toast('Circle paused.')})}}if(d.resume)run(null,async()=>{await api('/circles/'+d.resume+'/resume',{});await sync();await navigate();toast('Circle resumed.')})}catch(err){toast(err.message)}});
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&!busy)close()});window.addEventListener('hashchange',()=>{detailTab='overview';searchText='';navigate();window.scrollTo(0,0)});window.addEventListener('offline',()=>{$('#connection').innerHTML='<div class="notice warn">You’re offline. Reconnect before making changes or payments.</div>'});window.addEventListener('online',()=>{$('#connection').innerHTML='';backgroundRefresh()});
async function init(){try{demoAccounts=await api('/demo-accounts');const params=new URLSearchParams(location.hash.slice(1));if(params.has('confirmation_token')){const token=params.get('confirmation_token');history.replaceState(null,'',location.pathname+'#login');await api('/auth/confirm',{token});toast('Your email is confirmed.');await afterAuth();return}if(params.has('recovery_token')){recoveryToken=params.get('recovery_token');history.replaceState(null,'',location.pathname+'#reset-password')}const d=await api('/me');me=d.user;if(me)await sync();await navigate()}catch(e){layout('overview');$('#content').innerHTML=empty('Let’s get you connected.',e.message,'Try again','refresh')}}
let refreshRunning=false,lastInteraction=0;
for(const event of ['input','keydown','pointerdown'])document.addEventListener(event,()=>{lastInteraction=Date.now()},{passive:true});
const refreshSafe=()=>me&&!busy&&!document.hidden&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.activeElement?.isContentEditable&&!['checkout','account','receipt','login','signup','forgot-password','reset-password'].includes(route().split('/')[0])&&Date.now()-lastInteraction>2000;
async function backgroundRefresh(){if(refreshRunning||!refreshSafe())return;refreshRunning=true;const currentRoute=route(),epoch=navEpoch;try{const data=await api('/home');let detail=null;const parts=currentRoute.split('/');if(['circle','join','explore'].includes(parts[0])){const path=parts[0]==='circle'?'/circles/'+encodeURIComponent(parts[1]):parts[0]==='join'?'/invitations/'+encodeURIComponent(parts.slice(1).join('/')):'/explore';detail=await api(path)}if(!refreshSafe()||route()!==currentRoute||navEpoch!==epoch)return;const changed=JSON.stringify(me)!==JSON.stringify(data.user)||JSON.stringify(circles)!==JSON.stringify(data.circles)||detail&&JSON.stringify(detail)!==JSON.stringify(pageData);me=data.user;circles=data.circles;if(changed){const scroll=window.scrollY;layout(parts[0]);if(detail)pageData=detail;renderCurrent(parts[0],detail||pageData);window.scrollTo(0,scroll)}}catch{}finally{refreshRunning=false}}
setInterval(backgroundRefresh,15000);window.addEventListener('focus',backgroundRefresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)backgroundRefresh()});init();
